public class Monster : MonoBehaviour
{
    public bool isTrapped = false;
    public float trapDuration;
    public bool isLullaby = false;
    public int currentHealth { get; private set; }
    public MonsterScriptable monsterData;

    // 덫 상태 설정
    public void SetTrapped()
    {
        isTrapped = true;
        // 몬스터 움직임 정지 처리
        StartCoroutine(TrapCoroutine());
    }

    // 자장가 효과 설정  
    public void SetLullaby()
    {
        isLullaby = true;
        // 이동 속도 감소 처리
        StartCoroutine(LullabyCoroutine());
    }

    // 덫에서 해제
    public void ReleaseFromTrap()
    {
        isTrapped = false;
        // 정상 움직임 복원
    }

    // 자장가 효과 해제
    public void ReleaseFromLullaby()
    {
        isLullaby = false;
        // 이동 속도 정상화
    }

    // 데미지 처리
    public void TakeDamage(int damage, Vector3 weaponpos, float knockback, bool isHitByLog)
    {
        currentHealth -= damage;

        // 넉백 효과 적용
        if (knockback > 0)
        {
            Vector3 direction = (transform.position - weaponpos).normalized;
            GetComponent<Rigidbody>().AddForce(direction * knockback, ForceMode.Impulse);
        }

        if (currentHealth <= 0)
        {
            Die();
        }
    }

    // 몬스터 사망 처리
    public void Die()
    {
        // 화폐 및 점수 지급
        GameManager.gameManager.AddCurrency(monsterData.coin);
        GameManager.gameManager.AddScore(score);

        Destroy(gameObject);
    }
}

