public class MonsterSpawner : MonoBehaviour
{
    public GameObject spawner;
    private Wave currentWave;
    private int spawnMonsterCount = 0;
    private int spawnersLength;

    void Start()
    {
        spawnersLength = spawner.transform.childCount;
    }

    // 웨이브 시작
    public void StartWave(Wave wave)
    {
        currentWave = wave;
        spawnMonsterCount = 0;
        StartCoroutine("SpawnMonster");
    }

    // 몬스터 스폰 코루틴
    private IEnumerator SpawnMonster()
    {
        while (spawnMonsterCount < currentWave.maxMonsterCount)
        {
            // 랜덤 몬스터 타입 선택
            int monsterIndex = Random.Range(0, currentWave.monsterPrefabs.Length);

            // 랜덤 스폰 위치 선택
            int randomPosition = Random.Range(0, spawnersLength);

            // 몬스터 인스턴스 생성
            GameObject newMonster = Instantiate(
                currentWave.monsterPrefabs[monsterIndex],
                spawner.transform.GetChild(randomPosition).transform.position,
                spawner.transform.GetChild(randomPosition).transform.rotation
            );

            spawnMonsterCount++;
            GameManager.gameManager.AddMonster();

            // 다음 스폰까지 대기
            yield return new WaitForSeconds(currentWave.spawnTime);
        }

        // 스폰 완료 알림
        GameManager.gameManager.FinishSpawn();
    }
}

