public class GameManager : MonoBehaviour
{
    public static GameManager gameManager; // 싱글톤

    [Header("플레이어 상태")]
    public int maxHealth = 45;
    public int currentHealth;
    public int currency = 100;
    public int score = 0;
    public string studentId;

    [Header("게임 진행")]
    public int currentWave = 1;
    public int currentMonsterCount = 0;
    public bool spawnFinished = false;
    public int weaponLevel = 1;

    void Start()
    {
        currentHealth = maxHealth;
        UiManager.uiManager.UpdateHealthText(currentHealth, maxHealth);
        UiManager.uiManager.UpdateCurrencyText(currency);
    }

    // 체력 감소
    public void DecreaseHealth(int damage)
    {
        currentHealth -= damage;
        currentHealth = Mathf.Max(0, currentHealth);

        UiManager.uiManager.UpdateHealthText(currentHealth, maxHealth);

        if (currentHealth <= 0)
        {
            // 게임 오버 처리
            LoadGameOverScene();
        }
    }

    // 화폐 추가
    public void AddCurrency(int amount)
    {
        currency += amount;
        UiManager.uiManager.UpdateCurrencyText(currency);
    }

    // 화폐 소비
    public bool SpendCurrency(int amount)
    {
        if (currency >= amount)
        {
            currency -= amount;
            UiManager.uiManager.UpdateCurrencyText(currency);
            return true;
        }
        return false;
    }

    // 웨이브 증가
    public void PlusCurrentWave()
    {
        currentWave++;
    }

    // 몬스터 추가
    public void AddMonster()
    {
        currentMonsterCount++;
    }

    // 몬스터 처치
    public void DieMonster()
    {
        currentMonsterCount--;

        // 모든 몬스터 처치 시 스테이지 클리어 확인
        if (currentMonsterCount <= 0 && spawnFinished)
        {
            StageClear();
        }
    }

    // 스테이지 클리어
    public void StageClear()
    {
        Debug.Log("Stage Clear!");
        // 남은 체력에 따른 다양한 엔딩 처리
        GameClear(currentHealth);
    }

    // 게임 클리어 (체력별 엔딩)
    public void GameClear(int health)
    {
        if (health > 30)
        {
            // 좋은 엔딩
            SceneManager.LoadScene("GoodEndingScene");
        }
        else if (health > 0)
        {
            // 일반 엔딩  
            SceneManager.LoadScene("NormalEndingScene");
        }
        else
        {
            // 배드 엔딩
            SceneManager.LoadScene("BadEndingScene");
        }
    }
}

