// ItemSelect.cs - 아이템 선택 시스템
public class ItemSelect : MonoBehaviour
{
    public GameObject itemDisplay;
    public static string nowOn = "";
    public static List<KeyValuePair<string, GameObject>> items;

    public string content;
    public int cost;
    public Text displayContent;
    public Text displayCost;
    public Text displayMoney;

    public void Awake()
    {
        items = new List<KeyValuePair<string, GameObject>>();

        // 아이템 목록 초기화
        for (int i = 0; i < itemDisplay.transform.childCount; i++)
        {
            GameObject inObject = itemDisplay.transform.GetChild(i).gameObject;
            items.Add(new KeyValuePair<string, GameObject>(inObject.name, inObject));
        }

        nowOn = items[0].Key;
    }

    // 아이템 클릭 처리
    public void ItemClick()
    {
        string itemName = gameObject.name;

        if (nowOn == itemName) return; // 같은 아이템 재선택 방지

        // 이전 아이템 비활성화
        foreach (var item in items)
        {
            if (item.Key == nowOn)
            {
                item.Value.SetActive(false);
                break;
            }
        }

        // 새 아이템 활성화
        foreach (var item in items)
        {
            if (item.Key == itemName)
            {
                item.Value.SetActive(true);
                break;
            }
        }

        nowOn = itemName;

        // UI 업데이트
        displayContent.text = content;
        displayCost.text = cost.ToString();
        displayMoney.text = GameManager.gameManager.currency.ToString();

        // 구매 가능성에 따른 색상 변경
        if (GameManager.gameManager.currency >= cost)
        {
            displayCost.color = Color.green;
        }
        else
        {
            displayCost.color = Color.red;
        }
    }
}

