public class SkillCooldown : MonoBehaviour
{
    [Header("스킬 UI 요소들")]
    public GameObject[] hideSkillButton;
    public GameObject[] textPro;
    public TextMeshProUGUI[] skillCooldownText;
    public Image[] skillImage;
    public Button[] skillButtons;

    [Header("쿨다운 추적")]
    public float[] getSkillTime; // 각 스킬별 쿨다운 시간
    public bool[] skillUse;      // 스킬 사용 가능 여부

    void Start()
    {
        // 배열 크기만큼 초기화
        getSkillTime = new float[hideSkillButton.Length];
        skillUse = new bool[hideSkillButton.Length];

        // 모든 스킬을 사용 가능 상태로 초기화
        for (int i = 0; i < skillUse.Length; i++)
        {
            skillUse[i] = true;
        }
    }

    void Update()
    {
        // 각 스킬의 쿨다운 업데이트
        for (int i = 0; i < getSkillTime.Length; i++)
        {
            if (getSkillTime[i] > 0)
            {
                getSkillTime[i] -= Time.deltaTime;

                // UI 업데이트
                UpdateSkillUI(i);

                if (getSkillTime[i] <= 0)
                {
                    // 쿨다운 완료
                    FinishCooldown(i);
                }
            }
        }
    }

    // 스킬 쿨다운 시작
    public void HideSkillSetting(int skillIndex)
    {
        if (skillIndex < 0 || skillIndex >= getSkillTime.Length) return;

        // GameManager에서 웨이브별 스킬 데이터 가져오기
        float cooldownTime = GetSkillCooldownTime(skillIndex);

        getSkillTime[skillIndex] = cooldownTime;
        skillUse[skillIndex] = false;

        // 스킬 버튼 숨기기
        if (hideSkillButton[skillIndex] != null)
        {
            hideSkillButton[skillIndex].SetActive(false);
        }

        StartCoroutine(SkillCooldownCoroutine(skillIndex));
    }

    // 쿨다운 UI 업데이트
    private void UpdateSkillUI(int skillIndex)
    {
        float remainingTime = getSkillTime[skillIndex];
        float totalTime = GetSkillCooldownTime(skillIndex);

        // 남은 시간 텍스트 업데이트
        if (skillCooldownText[skillIndex] != null)
        {
            skillCooldownText[skillIndex].text = Mathf.Ceil(remainingTime).ToString();
        }

        // 이미지 Fill 업데이트
        if (skillImage[skillIndex] != null)
        {
            skillImage[skillIndex].fillAmount = remainingTime / totalTime;
        }

        // 버튼 비활성화
        if (skillButtons[skillIndex] != null)
        {
            skillButtons[skillIndex].interactable = false;
        }
    }

    // 쿨다운 완료 처리
    private void FinishCooldown(int skillIndex)
    {
        skillUse[skillIndex] = true;

        // UI 초기화
        if (skillCooldownText[skillIndex] != null)
        {
            skillCooldownText[skillIndex].text = "";
        }

        if (skillImage[skillIndex] != null)
        {
            skillImage[skillIndex].fillAmount = 0f;
        }

        if (skillButtons[skillIndex] != null)
        {
            skillButtons[skillIndex].interactable = true;
        }

        // 스킬 버튼 다시 표시
        if (hideSkillButton[skillIndex] != null)
        {
            hideSkillButton[skillIndex].SetActive(true);
        }
    }

    // 쿨다운 감소
    public void ReduceCooldown(float reductionAmount)
    {
        for (int i = 0; i < getSkillTime.Length; i++)
        {
            if (getSkillTime[i] > 0)
            {
                getSkillTime[i] -= reductionAmount;
                getSkillTime[i] = Mathf.Max(0, getSkillTime[i]);
            }
        }
    }

    // GameManager에서 웨이브별 스킬 쿨다운 시간 가져오기
    private float GetSkillCooldownTime(int skillIndex)
    {
        // 현재 웨이브에 따른 동적 쿨다운 시간 조정
        float baseTime = GameManager.gameManager.GetSkillData(skillIndex).cooldown;
        int currentWave = GameManager.gameManager.GetCurrentWave();

        return baseTime * (1f - currentWave * 0.05f); // 웨이브마다 5% 감소
    }

    // 쿨다운 코루틴
    private IEnumerator SkillCooldownCoroutine(int skillIndex)
    {
        while (getSkillTime[skillIndex] > 0)
        {
            yield return null;
        }
    }
}

