public class SkillPaperTowel : MonoBehaviour
{
    [Header("발사체 설정")]
    public GameObject paperToewlPrefab;
    public bool isCooldown = false;

    private Transform playerTransform;

    void Awake()
    {
        // 플레이어 Transform 찾기
        GameObject player = GameObject.FindWithTag("Player");
        if (player != null)
        {
            playerTransform = player.transform.root;
        }
    }

    // 페이퍼 타올 스킬 실행
    public IEnumerator PaperTowel()
    {
        if (isCooldown) yield break;

        isCooldown = true;

        // 플레이어 위치에서 페이퍼 타올 생성
        Vector3 spawnPosition = playerTransform.position;
        Vector3 forwardDirection = playerTransform.forward;

        GameObject paperTowel = Instantiate(
            paperToewlPrefab, 
            spawnPosition, 
            Quaternion.LookRotation(forwardDirection)
        );

        // GameManager에서 현재 웨이브의 스킬 데이터 가져오기
        SkillState skillData = GameManager.gameManager.GetCurrentSkillData();

        // 발사체 크기 설정
        float skillSize = skillData.objSize;
        paperTowel.transform.localScale = Vector3.one * skillSize;

        // 물리적 힘 적용
        Rigidbody rb = paperTowel.GetComponent<Rigidbody>();
        if (rb != null)
        {
            float force = skillData.force;
            rb.AddForce(forwardDirection * force, ForceMode.Impulse);
        }

        // 발사체 자동 파괴 시작
        StartCoroutine(DestroyPrefab(paperTowel));

        yield return null;
    }

    // 발사체 자동 파괴
    public IEnumerator DestroyPrefab(GameObject prefab)
    {
        yield return new WaitForSeconds(3f);

        if (prefab != null)
        {
            Destroy(prefab);
        }

        // 쿨다운 해제
        isCooldown = false;
    }

    // 스킬 사용 가능 여부 확인
    public bool CanUseSkill()
    {
        return !isCooldown;
    }

    // 쿨다운 상태 확인
    public bool IsOnCooldown()
    {
        return isCooldown;
    }

    // 강제 쿨다운 해제 (디버그용)
    public void ResetCooldown()
    {
        isCooldown = false;
    }
}
